def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Locate the uniform guide row or column.
    guide = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != bg:
            guide = ("row", r, grid[r][0])
            break
    if guide is None:
        for c in range(w):
            vals = {grid[r][c] for r in range(h)}
            if len(vals) == 1 and grid[0][c] != bg:
                guide = ("col", c, grid[0][c])
                break
    if guide is None:
        return [row[:] for row in grid]

    orient, index, guide_color = guide
    obj = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] != bg and grid[r][c] != guide_color]
    if not obj:
        return [row[:] for row in grid]

    out = [[bg] * w for _ in range(h)]
    # Retain the guide.
    if orient == "row":
        out[index] = grid[index][:]
        lo = min(r for r, c in obj)
        hi = max(r for r, c in obj)
        shift = index + 1 - lo if lo > index else index - 1 - hi if hi < index else 0
        moved = [(r + shift, c) for r, c in obj]
        far = max(r for r, c in moved) if max(r for r, c in moved) > index else min(r for r, c in moved)
        stripe = far + (1 if far > index else -1)
        for r, c in moved:
            if 0 <= r < h:
                out[r][c] = grid[r - shift][c]
        if 0 <= stripe < h:
            out[stripe] = [8] * w
    else:
        for r in range(h):
            out[r][index] = grid[r][index]
        lo = min(c for r, c in obj)
        hi = max(c for r, c in obj)
        shift = index + 1 - lo if lo > index else index - 1 - hi if hi < index else 0
        moved = [(r, c + shift) for r, c in obj]
        far = max(c for r, c in moved) if max(c for r, c in moved) > index else min(c for r, c in moved)
        stripe = far + (1 if far > index else -1)
        for r, c in moved:
            if 0 <= c < w:
                out[r][c] = grid[r][c - shift]
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8
    return out
